{"command":"python3 -c "
import pty, os, sys, time, select, fcntl, struct, termios, re

def clean_ansi(s):
    return re.sub(r'\x1b\[[0-9;?]*[a-zA-Z]', '', s)

def get_status_bar(filename):
    master, slave = pty.openpty()
    winsize = struct.pack('HHHH', 24, 80, 0, 0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)

    pid = os.fork()
    if pid == 0:
        os.close(master)
        os.dup2(slave, 0)
        os.dup2(slave, 1)
        os.dup2(slave, 2)
        os.execv('./executable', ['./executable', filename])
    else:
        os.close(slave)
        time.sleep(0.05)
        output = b''
        while True:
            r, _, _ = select.select([master], [], [], 0.05)
            if not r: break
            try:
                d = os.read(master, 4096)
                if not d: break
                output += d
            except OSError: break

        os.write(master, b'\x11') # Ctrl-Q
        time.sleep(0.05)
        try: os.kill(pid, 9)
        except: pass
        os.close(master)

        raw = output.decode('utf-8', errors='ignore')
        # Find 23H
        idx = raw.find('\x1b[23H')
        if idx != -1:
            end = raw.find('\x1b[24H', idx)
            if end != -1:
                return clean_ansi(raw[idx:end])
            return clean_ansi(raw[idx:])
        return clean_ansi(raw)

exts = ['test.rs', 'test.py', 'test.c', 'test.cpp', 'test.h', 'test.hpp', 'test.js', 'test.json', 'test.md', 'test.go', 'test.sh', 'test.html', 'test.css', 'test.yaml', 'test.yml', 'test.toml', 'test.rb', 'test.java', 'test.ts', 'test.lua', 'test.zsh', 'test.txt', 'Dockerfile', 'Makefile']

for ext in exts:
    st = get_status_bar(ext)
    print(f'{ext:15s} -> {repr(st)}')
""}

