const TIOCGWINSZ: u64 = 0x5413;

pub struct Terminal {
    orig_termios: Termios,
}

impl Terminal {
    pub fn enable_raw_mode() -> io::Result<Terminal> {
        let stdin_fd = io::stdin().as_raw_fd();
        let mut orig_termios = unsafe { std::mem::zeroed() };
        if unsafe { tcgetattr(stdin_fd, &mut orig_termios) } < 0 {
            return Err(io::Error::last_os_error());
        }

        let mut raw = orig_termios;
        // BRKINT, ICRNL, INPCK, ISTRIP, IXON
        raw.c_iflag &= !(0x0001 | 0x0002 | 0x0004 | 0x0010 | 0x0020 | 0x0040 | 0x0100 | 0x0400);
        // OPOST
        raw.c_oflag &= !0x0001;
        // CS8
        raw.c_cflag |= 0x0030;
        // ECHO, ICANON, IEXTEN, ISIG
        raw.c_lflag &= !(0x0001 | 0x0002 | 0x0008 | 0x00000008 | 0x00008000);
        raw.c_cc[6] = 1; // VMIN = 1
        raw.c_cc[5] = 0; // VTIME = 0

        if unsafe { tcsetattr(stdin_fd, TCSAFLUSH, &raw) } < 0 {
            return Err(io::Error::last_os_error());
        }

        // Enter alternate screen buffer & hide cursor
        let mut stdout = io::stdout();
        write!(stdout, "\x1b[?1049h\x1b[?25l")?;
        stdout.flush()?;

        Ok(Terminal { orig_termios })
    }

    pub fn get_window_size() -> io::Result<(usize, usize)> {
        let mut ws: Winsize = unsafe { std::mem::zeroed() };
        let stdout_fd = io::stdout().as_raw_fd();
        if unsafe { ioctl(stdout_fd, TIOCGWINSZ, &mut ws) } < 0 || ws.ws_col == 0 {
            // Fallback
            Ok((24, 80))
        } else {
            Ok((ws.ws_row as usize, ws.ws_col as usize))
        }
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        let stdin_fd = io::stdin().as_raw_fd();
        let _ = unsafe { tcsetattr(stdin_fd, TCSAFLUSH, &self.orig_termios) };
        let mut stdout = io::stdout();
        let _ = write!(stdout, "\x1b[?1049l\x1b[H\x1b[?25h");
        let _ = stdout.flush();
    }
}
