use std::io::{self, Write};
use crate::buffer::TextBuffer;
use crate::highlight::Highlight;
use crate::key::{read_key, Key};
use crate::row::char_width;
use crate::terminal::Terminal;

pub enum PromptType {
    SaveAs,
    Open,
    Search,
}

pub struct Editor {
    pub buffers: Vec<TextBuffer>,
    pub active_buf: usize,
    pub screen_rows: usize,
    pub screen_cols: usize,
    pub status_msg: String,
    pub status_msg_is_error: bool,
    pub prompt: Option<(PromptType, String)>,
    pub help_mode: bool,
    pub quit_times: usize,
    // Saved state for search cancel
    pub search_saved: Option<(usize, usize, usize, usize)>,
    pub search_match_idx: usize,
}

impl Editor {
    pub fn new(files: Vec<String>) -> io::Result<Self> {
        let (rows, cols) = Terminal::get_window_size()?;
        // Reserve 2 rows for status bar and message bar
        let screen_rows = if rows > 2 { rows - 2 } else { 1 };

        let mut buffers = Vec::new();
        if files.is_empty() {
            buffers.push(TextBuffer::new(None)?);
        } else {
            for f in files {
                buffers.push(TextBuffer::new(Some(f))?);
            }
        }

        Ok(Editor {
            buffers,
            active_buf: 0,
            screen_rows,
            screen_cols: cols,
            status_msg: "Ctrl-? for help".to_string(),
            status_msg_is_error: false,
            prompt: None,
            help_mode: false,
            quit_times: 0,
            search_saved: None,
            search_match_idx: 0,
        })
    }

    pub fn set_message(&mut self, msg: String, is_error: bool) {
        self.status_msg = msg;
        self.status_msg_is_error = is_error;
    }

    pub fn update_window_size(&mut self) -> io::Result<()> {
        let (rows, cols) = Terminal::get_window_size()?;
        self.screen_rows = if rows > 2 { rows - 2 } else { 1 };
        self.screen_cols = cols;
        Ok(())
    }

    pub fn run(&mut self) -> io::Result<()> {
        let _term = Terminal::enable_raw_mode()?;

        loop {
            self.refresh_screen()?;
            let key = match read_key() {
                Ok(k) => k,
                Err(_) => break,
            };

            if !self.process_keypress(key)? {
                break;
            }
        }
        Ok(())
    }

    pub fn process_keypress(&mut self, key: Key) -> io::Result<bool> {
        // If help mode is active, ANY keypress dismisses help mode and is consumed
        if self.help_mode {
            self.help_mode = false;
            return Ok(true);
        }

        // If in prompt mode, handle prompt input
        if self.prompt.is_some() {
            self.handle_prompt_key(key)?;
            return Ok(true);
        }

        let is_quit = key == Key::Ctrl('q');

        if !is_quit {
            self.quit_times = 0;
        }

        match key {
            Key::Ctrl('q') => {
                let any_dirty = self.buffers.iter().any(|b| b.dirty);
                if any_dirty && self.quit_times == 0 {
                    self.quit_times = 1;
                    self.set_message(
                        "At least one file has unsaved changes! Press ^Q again to quit or ^S to save".to_string(),
                        true,
                    );
                    return Ok(true);
                }
                return Ok(false);
            }
            Key::Ctrl('s') => {
                self.save_active_buffer()?;
            }
            Key::Ctrl('o') => {
                self.prompt = Some((PromptType::Open, String::new()));
            }
            Key::Ctrl('x') => {
                if !self.buffers.is_empty() {
                    self.active_buf = (self.active_buf + 1) % self.buffers.len();
                }
            }
            Key::Alt('x') => {
                if !self.buffers.is_empty() {
                    if self.active_buf == 0 {
                        self.active_buf = self.buffers.len() - 1;
                    } else {
                        self.active_buf -= 1;
                    }
                }
            }
            Key::Ctrl('g') => {
                let buf = &self.buffers[self.active_buf];
                self.search_saved = Some((buf.cx, buf.cy, buf.row_off, buf.col_off));
                self.search_match_idx = 0;
                self.prompt = Some((PromptType::Search, String::new()));
            }
            Key::Ctrl('?') => {
                self.help_mode = true;
            }
            Key::Ctrl('l') => {
                self.update_window_size()?;
            }
            Key::Ctrl('u') => {
                self.buffers[self.active_buf].undo();
            }
            Key::Ctrl('r') => {
                self.buffers[self.active_buf].redo();
            }
            // Navigation & editing dispatches
            _ => self.handle_normal_key(key)?,
        }

        Ok(true)
    }

    fn save_active_buffer(&mut self) -> io::Result<()> {
        let has_name = self.buffers[self.active_buf].filename.is_some();
        if !has_name {
            self.prompt = Some((PromptType::SaveAs, String::new()));
        } else {
            match self.buffers[self.active_buf].save() {
                Ok(written) => {
                    let path = self.buffers[self.active_buf].filename.clone().unwrap();
                    self.set_message(format!("{} bytes written to {}", written, path), false);
                }
                Err(e) => {
                    self.set_message(format!("Could not save: {}", e), true);
                }
            }
        }
        Ok(())
    }

    fn handle_normal_key(&mut self, key: Key) -> io::Result<()> {
        let buf = &mut self.buffers[self.active_buf];

        match key {
            Key::Char(c) => buf.insert_char(c),
            Key::Enter | Key::Ctrl('m') => buf.insert_newline(),
            Key::Backspace | Key::Ctrl('h') => buf.delete_char(),
            Key::Delete | Key::Ctrl('d') => buf.delete_next_char(),
            Key::Ctrl('w') => buf.delete_word(),
            Key::Ctrl('k') => buf.delete_to_end_of_line(),
            Key::Ctrl('j') => buf.delete_to_head_of_line(),

            Key::Left | Key::Ctrl('b') => buf.move_cursor_left(),
            Key::Right | Key::Ctrl('f') => buf.move_cursor_right(),
            Key::Up | Key::Ctrl('p') => buf.move_cursor_up(),
            Key::Down | Key::Ctrl('n') => buf.move_cursor_down(),

            Key::CtrlLeft | Key::Alt('b') => buf.move_prev_word(),
            Key::CtrlRight | Key::Alt('f') => buf.move_next_word(),
            Key::CtrlUp | Key::Alt('p') => buf.move_prev_paragraph(),
            Key::CtrlDown | Key::Alt('n') => buf.move_next_paragraph(),

            Key::Home | Key::Ctrl('a') | Key::AltLeft => buf.cx = 0,
            Key::End | Key::Ctrl('e') | Key::AltRight => {
                if buf.cy < buf.rows.len() {
                    buf.cx = buf.rows[buf.cy].chars.chars().count();
                }
            }
            Key::Alt('<') => {
                buf.cy = 0;
                buf.cx = 0;
            }
            Key::Alt('>') => {
                buf.cy = buf.rows.len();
                buf.cx = 0;
            }
            Key::PageDown | Key::Ctrl('v') | Key::Ctrl('[') => {
                let times = self.screen_rows;
                for _ in 0..times {
                    buf.move_cursor_down();
                }
            }
            Key::PageUp | Key::Alt('v') | Key::Ctrl(']') => {
                let times = self.screen_rows;
                for _ in 0..times {
                    buf.move_cursor_up();
                }
            }
            _ => {}
        }
        Ok(())
    }

    fn handle_prompt_key(&mut self, key: Key) -> io::Result<()> {
        let (prompt_type, ref mut input) = self.prompt.as_mut().unwrap();

        match key {
            Key::Esc | Key::Ctrl('g') => {
                if matches!(prompt_type, PromptType::Search) {
                    if let Some((cx, cy, row_off, col_off)) = self.search_saved {
                        let buf = &mut self.buffers[self.active_buf];
                        buf.cx = cx;
                        buf.cy = cy;
                        buf.row_off = row_off;
                        buf.col_off = col_off;
                    }
                }
                self.prompt = None;
                self.set_message("Ctrl-? for help".to_string(), false);
            }
            Key::Enter | Key::Ctrl('m') => {
                let input_str = input.clone();
                let p_type = match prompt_type {
                    PromptType::SaveAs => PromptType::SaveAs,
                    PromptType::Open => PromptType::Open,
                    PromptType::Search => PromptType::Search,
                };
                self.prompt = None;

                match p_type {
                    PromptType::SaveAs => {
                        if !input_str.is_empty() {
                            self.buffers[self.active_buf].filename = Some(input_str.clone());
                            match self.buffers[self.active_buf].save() {
                                Ok(written) => {
                                    self.set_message(
                                        format!("{} bytes written to {}", written, input_str),
                                        false,
                                    );
                                }
                                Err(e) => {
                                    self.set_message(format!("Could not save: {}", e), true);
                                }
                            }
                        }
                    }
                    PromptType::Open => {
                        if input_str.is_empty() {
                            self.buffers.push(TextBuffer::new(None)?);
                            self.active_buf = self.buffers.len() - 1;
                        } else {
                            // Check if already open
                            let existing = self
                                .buffers
                                .iter()
                                .position(|b| b.filename.as_deref() == Some(&input_str));
                            if let Some(idx) = existing {
                                self.active_buf = idx;
                            } else {
                                self.buffers.push(TextBuffer::new(Some(input_str))?);
                                self.active_buf = self.buffers.len() - 1;
                            }
                        }
                    }
                    PromptType::Search => {
                        self.set_message("Ctrl-? for help".to_string(), false);
                    }
                }
            }
            Key::Backspace | Key::Ctrl('h') => {
                input.pop();
                if matches!(prompt_type, PromptType::Search) {
                    self.do_incremental_search(input, false)?;
                }
            }
            Key::Right | Key::Ctrl('f') | Key::Ctrl('n') => {
                if matches!(prompt_type, PromptType::Search) {
                    self.do_incremental_search(input, true)?;
                }
            }
            Key::Left | Key::Ctrl('b') | Key::Ctrl('p') => {
                if matches!(prompt_type, PromptType::Search) {
                    self.do_incremental_search_backward(input)?;
                }
            }
            Key::Char(c) => {
                input.push(c);
                if matches!(prompt_type, PromptType::Search) {
                    self.do_incremental_search(input, false)?;
                }
            }
            _ => {}
        }
        Ok(())
    }

    fn do_incremental_search(&mut self, query: &str, next: bool) -> io::Result<()> {
        if query.is_empty() {
            return Ok(());
        }
        let buf = &mut self.buffers[self.active_buf];
        let num_rows = buf.rows.len();

        let start_y = if next { buf.cy } else { 0 };
        let start_x = if next { buf.cx + 1 } else { 0 };

        for i in 0..num_rows {
            let y = (start_y + i) % num_rows;
            let row = &buf.rows[y];
            let search_from = if y == start_y && next { start_x } else { 0 };

            if search_from <= row.chars.chars().count() {
                let row_str: String = row.chars.chars().skip(search_from).collect();
                if let Some(pos) = row_str.find(query) {
                    let char_pos = row_str[..pos].chars().count() + search_from;
                    buf.cy = y;
                    buf.cx = char_pos;
                    break;
                }
            }
        }
        Ok(())
    }

    fn do_incremental_search_backward(&mut self, query: &str) -> io::Result<()> {
        if query.is_empty() {
            return Ok(());
        }
        let buf = &mut self.buffers[self.active_buf];
        let num_rows = buf.rows.len();
        if num_rows == 0 {
            return Ok(());
        }

        let start_y = buf.cy;
        for i in 0..num_rows {
            let y = (start_y + num_rows - i) % num_rows;
            let row = &buf.rows[y];

            let row_chars: Vec<char> = row.chars.chars().collect();
            let limit = if y == start_y && buf.cx > 0 {
                buf.cx - 1
            } else {
                row_chars.len()
            };

            let line_str: String = row_chars[..limit.min(row_chars.len())].iter().collect();
            let matches: Vec<(usize, &str)> = line_str.match_indices(query).collect();
            if let Some((pos, _)) = matches.last() {
                let char_pos = line_str[..*pos].chars().count();
                buf.cy = y;
                buf.cx = char_pos;
                break;
            }
        }
        Ok(())
    }

    pub fn refresh_screen(&mut self) -> io::Result<()> {
        let active = self.active_buf;
        let buf = &mut self.buffers[active];

        // Ensure cursor is visible (scroll offsets)
        if buf.cy < buf.rows.len() {
            let rx = buf.rows[buf.cy].cx_to_rx(buf.cx);
            if buf.cy < buf.row_off {
                buf.row_off = buf.cy;
            }
            if buf.cy >= buf.row_off + self.screen_rows {
                buf.row_off = buf.cy - self.screen_rows + 1;
            }
            if rx < buf.col_off {
                buf.col_off = rx;
            }
            if rx >= buf.col_off + self.screen_cols {
                buf.col_off = rx - self.screen_cols + 1;
            }
        } else {
            if buf.cy < buf.row_off {
                buf.row_off = buf.cy;
            }
            if buf.cy >= buf.row_off + self.screen_rows {
                buf.row_off = buf.cy - self.screen_rows + 1;
            }
            buf.col_off = 0;
        }

        let mut output = String::with_capacity(8192);
        output.push_str("\x1b[?25l"); // Hide cursor
        output.push_str("\x1b[39;0m"); // Reset colors

        // Render help screen or buffer rows
        if self.help_mode {
            self.render_help(&mut output);
        } else {
            self.render_rows(&mut output);
        }

        // Render status bar and message bar
        self.render_status_bar(&mut output);
        self.render_message_bar(&mut output);

        // Position cursor
        let cursor_y = (buf.cy.saturating_sub(buf.row_off) + 1).min(self.screen_rows);
        let cursor_x = if self.help_mode {
            1
        } else if let Some((ref p_type, ref input)) = self.prompt {
            match p_type {
                PromptType::SaveAs => 10 + input.chars().count(),
                PromptType::Open => 7 + input.chars().count(),
                PromptType::Search => 9 + input.chars().count(),
            }
        } else {
            let rx = if buf.cy < buf.rows.len() {
                buf.rows[buf.cy].cx_to_rx(buf.cx)
            } else {
                0
            };
            (rx.saturating_sub(buf.col_off) + 1).min(self.screen_cols)
        };

        let cursor_row = if self.prompt.is_some() {
            self.screen_rows + 2
        } else {
            cursor_y
        };

        output.push_str(&format!("\x1b[{};{}H", cursor_row, cursor_x));
        output.push_str("\x1b[?25h"); // Show cursor

        let mut stdout = io::stdout();
        stdout.write_all(output.as_bytes())?;
        stdout.flush()?;

        Ok(())
    }

    fn render_rows(&self, output: &mut String) {
        let buf = &self.buffers[self.active_buf];
        let search_query = match self.prompt {
            Some((PromptType::Search, ref q)) if !q.is_empty() => Some(q.as_str()),
            _ => None,
        };

        for y in 0..self.screen_rows {
            let file_row = y + buf.row_off;
            output.push_str(&format!("\x1b[{}H", y + 1));

            if file_row < buf.rows.len() {
                let row = &buf.rows[file_row];
                let render_chars: Vec<char> = row.render.chars().collect();
                let len = render_chars.len();

                let mut col = 0;
                let mut screen_col = 0;

                while col < len && screen_col < self.screen_cols {
                    if col >= buf.col_off {
                        let c = render_chars[col];
                        let w = char_width(c);
                        if screen_col + w > self.screen_cols {
                            break;
                        }

                        // Check search match highlight
                        let mut match_type = None;
                        if let Some(q) = search_query {
                            if let Some(pos) = row.render.find(q) {
                                let q_chars = q.chars().count();
                                let match_start = row.render[..pos].chars().count();
                                if col >= match_start && col < match_start + q_chars {
                                    if file_row == buf.cy && match_start == buf.cx {
                                        match_type = Some(Highlight::MatchCurrent);
                                    } else {
                                        match_type = Some(Highlight::MatchOther);
                                    }
                                }
                            }
                        }

                        let hl = match_type.unwrap_or(row.hl[col]);
                        output.push_str(hl.to_ansi());
                        output.push(c);
                        screen_col += w;
                    }
                    col += 1;
                }
                output.push_str("\x1b[39;0m\x1b[K");
            } else {
                if buf.rows.is_empty() && y == self.screen_rows / 3 && !buf.dirty {
                    let welcome = "Kiro editor -- version 0.4.3";
                    let w_len = welcome.len();
                    let padding = (self.screen_cols.saturating_sub(w_len)) / 2;

                    output.push_str("\x1b[37m~\x1b[39;0m");
                    if padding > 1 {
                        for _ in 0..padding - 1 {
                            output.push(' ');
                        }
                    }
                    output.push_str(welcome);
                    output.push_str("\x1b[K");
                } else {
                    output.push_str("\x1b[37m~\x1b[39;0m\x1b[K");
                }
            }
        }
    }

    fn render_help(&self, output: &mut String) {
        let help_entries: &[(&str, &str)] = &[
            ("Ctrl-Q", "Quit"),
            ("Ctrl-S", "Save to file"),
            ("Ctrl-O", "Open text buffer"),
            ("Ctrl-X", "Next text buffer"),
            ("Alt-X", "Previous text buffer"),
            ("Ctrl-P or UP", "Move cursor up"),
            ("Ctrl-N or DOWN", "Move cursor down"),
            ("Ctrl-F or RIGHT", "Move cursor right"),
            ("Ctrl-B or LEFT", "Move cursor left"),
            ("Ctrl-A or Alt-LEFT or HOME", "Move cursor to head of line"),
            ("Ctrl-E or Alt-RIGHT or END", "Move cursor to end of line"),
            ("Ctrl-[ or Ctrl-V or PAGE DOWN", "Next page"),
            ("Ctrl-] or Alt-V or PAGE UP", "Previous page"),
            ("Alt-F or Ctrl-RIGHT", "Move cursor to next word"),
            ("Alt-B or Ctrl-LEFT", "Move cursor to previous word"),
            ("Alt-N or Ctrl-DOWN", "Move cursor to next paragraph"),
            ("Alt-P or Ctrl-UP", "Move cursor to previous paragraph"),
            ("Alt-<", "Move cursor to top of file"),
            ("Alt->", "Move cursor to bottom of file"),
            ("Ctrl-H or BACKSPACE", "Delete character"),
            ("Ctrl-D or DELETE", "Delete next character"),
            ("Ctrl-W", "Delete a word"),
            ("Ctrl-J", "Delete until head of line"),
            ("Ctrl-K", "Delete until end of line"),
            ("Ctrl-U", "Undo last change"),
            ("Ctrl-R", "Redo last undo change"),
            ("Ctrl-G", "Search text"),
            ("Ctrl-M", "New line"),
            ("Ctrl-L", "Refresh screen"),
            ("Ctrl-?", "Show this help"),
        ];

        for y in 0..self.screen_rows {
            output.push_str(&format!("\x1b[{}H", y + 1));
            if y < help_entries.len() {
                let (key, desc) = help_entries[y];
                output.push_str(&format!(
                    "       \x1b[96m{:30}\x1b[39;0m: {}\x1b[K",
                    key, desc
                ));
            } else {
                output.push_str("\x1b[37m~\x1b[39;0m\x1b[K");
            }
        }
    }

    fn render_status_bar(&self, output: &mut String) {
        let row_idx = self.screen_rows + 1;
        output.push_str(&format!("\x1b[{}H\x1b[7m", row_idx));

        let buf = &self.buffers[self.active_buf];
        let filename = buf.filename.as_deref().unwrap_or("[No Name]");
        let modified = if buf.dirty { " (modified)" } else { "" };
        let total_bufs = self.buffers.len();
        let buf_idx = self.active_buf + 1;

        let left = format!("\"{}\" - {}/{}{}", filename, buf_idx, total_bufs, modified);

        let lang = buf.syntax.map_or("plain", |s| s.name);
        let total_lines = buf.rows.len().max(1);
        let line_no = (buf.cy + 1).min(total_lines);
        let right = format!("{} {}/{}", lang, line_no, total_lines);

        let mut status = left;
        let spaces = self.screen_cols.saturating_sub(status.chars().count() + right.chars().count());
        for _ in 0..spaces {
            status.push(' ');
        }
        status.push_str(&right);

        // Truncate to screen_cols if needed
        let status_chars: String = status.chars().take(self.screen_cols).collect();
        output.push_str(&status_chars);
        output.push_str("\x1b[39;0m");
    }

    fn render_message_bar(&self, output: &mut String) {
        let row_idx = self.screen_rows + 2;
        output.push_str(&format!("\x1b[{}H", row_idx));

        if let Some((ref prompt_type, ref input)) = self.prompt {
            let (label, suffix) = match prompt_type {
                PromptType::SaveAs => ("Save as: ", " (^G or ESC to cancel)"),
                PromptType::Open => ("Open: ", " (Empty name for new text buffer, ^G or ESC to cancel)"),
                PromptType::Search => (
                    "Search: ",
                    " (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)",
                ),
            };
            let mut p_text = format!("{}{}{}", label, input, suffix);
            p_text.truncate(self.screen_cols);
            output.push_str(&p_text);
            output.push_str("\x1b[K");
        } else {
            if self.status_msg_is_error {
                output.push_str("\x1b[97m\x1b[41m");
            }
            let mut msg = self.status_msg.clone();
            msg.truncate(self.screen_cols);
            output.push_str(&msg);
            if self.status_msg_is_error {
                output.push_str("\x1b[39;0m");
            }
            output.push_str("\x1b[K");
        }
    }
}
EOF
"}

