use std::fs::File;
use std::io::{self, BufRead, BufReader, Write};
use crate::highlight::{find_syntax, Syntax};
use crate::row::Row;

#[derive(Clone, Debug)]
pub struct BufferSnapshot {
    pub rows: Vec<String>,
    pub cx: usize,
    pub cy: usize,
    pub dirty: bool,
}

pub struct TextBuffer {
    pub filename: Option<String>,
    pub rows: Vec<Row>,
    pub cx: usize,
    pub cy: usize,
    pub row_off: usize,
    pub col_off: usize,
    pub dirty: bool,
    pub syntax: Option<&'static Syntax>,
    pub undo_stack: Vec<BufferSnapshot>,
    pub redo_stack: Vec<BufferSnapshot>,
    pub initial_state: Vec<String>,
}

impl TextBuffer {
    pub fn new(filename: Option<String>) -> io::Result<Self> {
        let mut buf = TextBuffer {
            filename: filename.clone(),
            rows: Vec::new(),
            cx: 0,
            cy: 0,
            row_off: 0,
            col_off: 0,
            dirty: false,
            syntax: None,
            undo_stack: Vec::new(),
            redo_stack: Vec::new(),
            initial_state: Vec::new(),
        };

        if let Some(ref path) = filename {
            buf.syntax = find_syntax(path);
            if std::path::Path::new(path).exists() {
                let file = File::open(path)?;
                let reader = BufReader::new(file);
                for line in reader.lines() {
                    let l = line?;
                    buf.rows.push(Row::new(l));
                }
            }
        }

        buf.initial_state = buf.rows.iter().map(|r| r.chars.clone()).collect();
        buf.update_syntax_all();
        Ok(buf)
    }

    pub fn update_syntax_all(&mut self) {
        let mut in_multi = false;
        for row in &mut self.rows {
            in_multi = row.update_syntax(self.syntax, in_multi);
        }
    }

    pub fn save_snapshot(&mut self) {
        let snapshot = BufferSnapshot {
            rows: self.rows.iter().map(|r| r.chars.clone()).collect(),
            cx: self.cx,
            cy: self.cy,
            dirty: self.dirty,
        };
        self.undo_stack.push(snapshot);
        self.redo_stack.clear();
    }

    pub fn undo(&mut self) {
        if let Some(snap) = self.undo_stack.pop() {
            let current = BufferSnapshot {
                rows: self.rows.iter().map(|r| r.chars.clone()).collect(),
                cx: self.cx,
                cy: self.cy,
                dirty: self.dirty,
            };
            self.redo_stack.push(current);

            self.rows = snap.rows.into_iter().map(Row::new).collect();
            self.cx = snap.cx;
            self.cy = snap.cy;
            self.dirty = snap.dirty;
            self.update_syntax_all();
        }
    }

    pub fn redo(&mut self) {
        if let Some(snap) = self.redo_stack.pop() {
            let current = BufferSnapshot {
                rows: self.rows.iter().map(|r| r.chars.clone()).collect(),
                cx: self.cx,
                cy: self.cy,
                dirty: self.dirty,
            };
            self.undo_stack.push(current);

            self.rows = snap.rows.into_iter().map(Row::new).collect();
            self.cx = snap.cx;
            self.cy = snap.cy;
            self.dirty = snap.dirty;
            self.update_syntax_all();
        }
    }

    pub fn save(&mut self) -> io::Result<usize> {
        let path = match self.filename {
            Some(ref p) => p.clone(),
            None => return Err(io::Error::new(io::ErrorKind::Other, "No filename")),
        };

        let mut file = File::create(&path)?;
        let mut written = 0;
        for row in &self.rows {
            file.write_all(row.chars.as_bytes())?;
            written += row.chars.len();
            file.write_all(b"\n")?;
            written += 1;
        }
        file.flush()?;

        self.dirty = false;
        self.syntax = find_syntax(&path);
        self.update_syntax_all();

        Ok(written)
    }

    pub fn insert_char(&mut self, c: char) {
        self.save_snapshot();
        if self.cy == self.rows.len() {
            self.rows.push(Row::new(String::new()));
        }

        let row = &mut self.rows[self.cy];
        let mut chars: Vec<char> = row.chars.chars().collect();
        if self.cx > chars.len() {
            self.cx = chars.len();
        }
        chars.insert(self.cx, c);
        row.chars = chars.into_iter().collect();
        row.update_render();

        self.cx += 1;
        self.dirty = true;
        self.update_syntax_all();
    }

    pub fn insert_newline(&mut self) {
        self.save_snapshot();
        if self.cy == self.rows.len() {
            self.rows.push(Row::new(String::new()));
            self.cy += 1;
            self.cx = 0;
            self.dirty = true;
            self.update_syntax_all();
            return;
        }

        let chars: Vec<char> = self.rows[self.cy].chars.chars().collect();
        let split_idx = self.cx.min(chars.len());
        let left: String = chars[..split_idx].iter().collect();
        let right: String = chars[split_idx..].iter().collect();

        self.rows[self.cy].chars = left;
        self.rows[self.cy].update_render();

        self.rows.insert(self.cy + 1, Row::new(right));
        self.cy += 1;
        self.cx = 0;
        self.dirty = true;
        self.update_syntax_all();
    }

    pub fn delete_char(&mut self) {
        if self.cy == self.rows.len() && self.cx == 0 {
            return;
        }

        self.save_snapshot();
        if self.cx > 0 {
            let row = &mut self.rows[self.cy];
            let mut chars: Vec<char> = row.chars.chars().collect();
            if self.cx <= chars.len() {
                chars.remove(self.cx - 1);
                row.chars = chars.into_iter().collect();
                row.update_render();
                self.cx -= 1;
                self.dirty = true;
            }
        } else if self.cy > 0 {
            let current_row_chars = self.rows.remove(self.cy).chars;
            self.cy -= 1;
            let prev_row = &mut self.rows[self.cy];
            self.cx = prev_row.chars.chars().count();
            prev_row.chars.push_str(&current_row_chars);
            prev_row.update_render();
            self.dirty = true;
        }
        self.update_syntax_all();
    }

    pub fn delete_next_char(&mut self) {
        if self.cy >= self.rows.len() {
            return;
        }

        self.save_snapshot();
        let char_count = self.rows[self.cy].chars.chars().count();
        if self.cx < char_count {
            let row = &mut self.rows[self.cy];
            let mut chars: Vec<char> = row.chars.chars().collect();
            chars.remove(self.cx);
            row.chars = chars.into_iter().collect();
            row.update_render();
            self.dirty = true;
        } else if self.cy + 1 < self.rows.len() {
            let next_row_chars = self.rows.remove(self.cy + 1).chars;
            let row = &mut self.rows[self.cy];
            row.chars.push_str(&next_row_chars);
            row.update_render();
            self.dirty = true;
        }
        self.update_syntax_all();
    }

    pub fn delete_word(&mut self) {
        if self.cx == 0 {
            self.delete_char();
            return;
        }
        self.save_snapshot();
        if self.cy < self.rows.len() {
            let chars: Vec<char> = self.rows[self.cy].chars.chars().collect();
            let mut start = self.cx.min(chars.len());
            while start > 0 && is_word_sep(chars[start - 1]) {
                start -= 1;
            }
            while start > 0 && !is_word_sep(chars[start - 1]) {
                start -= 1;
            }
            let mut new_chars = chars[..start].to_vec();
            if self.cx < chars.len() {
                new_chars.extend_from_slice(&chars[self.cx..]);
            }
            self.rows[self.cy].chars = new_chars.into_iter().collect();
            self.rows[self.cy].update_render();
            self.cx = start;
            self.dirty = true;
            self.update_syntax_all();
        }
    }

    pub fn delete_to_end_of_line(&mut self) {
        if self.cy < self.rows.len() {
            self.save_snapshot();
            let chars: Vec<char> = self.rows[self.cy].chars.chars().collect();
            let new_chars: String = chars[..self.cx.min(chars.len())].iter().collect();
            self.rows[self.cy].chars = new_chars;
            self.rows[self.cy].update_render();
            self.dirty = true;
            self.update_syntax_all();
        }
    }

    pub fn delete_to_head_of_line(&mut self) {
        if self.cy < self.rows.len() {
            self.save_snapshot();
            let chars: Vec<char> = self.rows[self.cy].chars.chars().collect();
            let start = self.cx.min(chars.len());
            let new_chars: String = chars[start..].iter().collect();
            self.rows[self.cy].chars = new_chars;
            self.rows[self.cy].update_render();
            self.cx = 0;
            self.dirty = true;
            self.update_syntax_all();
        }
    }

    pub fn move_cursor_left(&mut self) {
        if self.cx > 0 {
            self.cx -= 1;
        } else if self.cy > 0 {
            self.cy -= 1;
            self.cx = self.rows[self.cy].chars.chars().count();
        }
    }

    pub fn move_cursor_right(&mut self) {
        if self.cy < self.rows.len() {
            let row_len = self.rows[self.cy].chars.chars().count();
            if self.cx < row_len {
                self.cx += 1;
            } else if self.cy < self.rows.len() {
                self.cy += 1;
                self.cx = 0;
            }
        }
    }

    pub fn move_cursor_up(&mut self) {
        if self.cy > 0 {
            self.cy -= 1;
            self.snap_cx_to_row_len();
        }
    }

    pub fn move_cursor_down(&mut self) {
        if self.cy < self.rows.len() {
            self.cy += 1;
            self.snap_cx_to_row_len();
        }
    }

    pub fn move_next_word(&mut self) {
        if self.cy >= self.rows.len() {
            return;
        }
        let chars: Vec<char> = self.rows[self.cy].chars.chars().collect();
        let len = chars.len();

        if self.cx >= len {
            if self.cy + 1 <= self.rows.len() {
                self.cy += 1;
                self.cx = 0;
            }
            return;
        }

        let mut i = self.cx;
        while i < len && !is_word_sep(chars[i]) {
            i += 1;
        }
        while i < len && is_word_sep(chars[i]) {
            i += 1;
        }

        if i >= len {
            if self.cy + 1 <= self.rows.len() {
                self.cy += 1;
                self.cx = 0;
            } else {
                self.cx = len;
            }
        } else {
            self.cx = i;
        }
    }

    pub fn move_prev_word(&mut self) {
        if self.cx == 0 {
            if self.cy > 0 {
                self.cy -= 1;
                self.cx = self.rows[self.cy].chars.chars().count();
            }
            return;
        }

        let chars: Vec<char> = self.rows[self.cy].chars.chars().collect();
        let mut i = self.cx;

        while i > 0 && is_word_sep(chars[i - 1]) {
            i -= 1;
        }
        while i > 0 && !is_word_sep(chars[i - 1]) {
            i -= 1;
        }
        self.cx = i;
    }

    pub fn move_next_paragraph(&mut self) {
        if self.cy >= self.rows.len() {
            return;
        }
        let mut y = self.cy + 1;
        while y < self.rows.len() && !self.rows[y].chars.trim().is_empty() {
            y += 1;
        }
        while y < self.rows.len() && self.rows[y].chars.trim().is_empty() {
            y += 1;
        }
        self.cy = y.min(self.rows.len());
        self.cx = 0;
    }

    pub fn move_prev_paragraph(&mut self) {
        if self.cy == 0 {
            self.cx = 0;
            return;
        }
        let mut y = self.cy - 1;
        while y > 0 && self.rows[y].chars.trim().is_empty() {
            y -= 1;
        }
        while y > 0 && !self.rows[y - 1].chars.trim().is_empty() {
            y -= 1;
        }
        self.cy = y;
        self.cx = 0;
    }

    pub fn snap_cx_to_row_len(&mut self) {
        if self.cy < self.rows.len() {
            let row_len = self.rows[self.cy].chars.chars().count();
            if self.cx > row_len {
                self.cx = row_len;
            }
        } else {
            self.cx = 0;
        }
    }
}

fn is_word_sep(c: char) -> bool {
    c.is_whitespace() || c == '\0' || ",.()+-/*=~%<>[]:;{}#&|!?\"'".contains(c)
}
