use std::io::{self, Read};
use std::os::unix::io::AsRawFd;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Key {
    Char(char),
    Ctrl(char),
    Alt(char),
    Up,
    Down,
    Left,
    Right,
    CtrlUp,
    CtrlDown,
    CtrlLeft,
    CtrlRight,
    AltUp,
    AltDown,
    AltLeft,
    AltRight,
    Home,
    End,
    PageUp,
    PageDown,
    Delete,
    Backspace,
    Enter,
    Tab,
    Esc,
}

pub fn read_key() -> io::Result<Key> {
    let mut stdin = io::stdin();
    let mut buf = [0u8; 1];

    if stdin.read(&mut buf)? == 0 {
        return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "EOF"));
    }

    let b = buf[0];

    match b {
        27 => {
            if !has_input()? {
                return Ok(Key::Esc);
            }
            let mut seq = [0u8; 1];
            if stdin.read(&mut seq)? == 0 {
                return Ok(Key::Esc);
            }
            match seq[0] {
                b'[' => {
                    let mut seq2 = [0u8; 1];
                    if stdin.read(&mut seq2)? == 0 {
                        return Ok(Key::Esc);
                    }
                    match seq2[0] {
                        b'A' => Ok(Key::Up),
                        b'B' => Ok(Key::Down),
                        b'C' => Ok(Key::Right),
                        b'D' => Ok(Key::Left),
                        b'H' => Ok(Key::Home),
                        b'F' => Ok(Key::End),
                        b'<' => Ok(Key::Alt('<')),
                        b'>' => Ok(Key::Alt('>')),
                        b'1'..=b'8' => {
                            let mut seq3 = [0u8; 1];
                            if stdin.read(&mut seq3)? == 0 {
                                return Ok(Key::Esc);
                            }
                            if seq3[0] == b'~' {
                                match seq2[0] {
                                    b'1' | b'7' => Ok(Key::Home),
                                    b'3' => Ok(Key::Delete),
                                    b'4' | b'8' => Ok(Key::End),
                                    b'5' => Ok(Key::PageUp),
                                    b'6' => Ok(Key::PageDown),
                                    _ => Ok(Key::Esc),
                                }
                            } else if seq3[0] == b';' {
                                let mut seq4 = [0u8; 2];
                                if stdin.read_exact(&mut seq4).is_ok() {
                                    match (seq4[0], seq4[1]) {
                                        (b'5', b'A') => Ok(Key::CtrlUp),
                                        (b'5', b'B') => Ok(Key::CtrlDown),
                                        (b'5', b'C') => Ok(Key::CtrlRight),
                                        (b'5', b'D') => Ok(Key::CtrlLeft),
                                        (b'3', b'A') | (b'9', b'A') => Ok(Key::AltUp),
                                        (b'3', b'B') | (b'9', b'B') => Ok(Key::AltDown),
                                        (b'3', b'C') | (b'9', b'C') => Ok(Key::AltRight),
                                        (b'3', b'D') | (b'9', b'D') => Ok(Key::AltLeft),
                                        _ => Ok(Key::Esc),
                                    }
                                } else {
                                    Ok(Key::Esc)
                                }
                            } else {
                                Ok(Key::Esc)
                            }
                        }
                        _ => Ok(Key::Esc),
                    }
                }
                b'O' => {
                    let mut seq2 = [0u8; 1];
                    if stdin.read(&mut seq2)? == 0 {
                        return Ok(Key::Esc);
                    }
                    match seq2[0] {
                        b'A' => Ok(Key::Up),
                        b'B' => Ok(Key::Down),
                        b'C' => Ok(Key::Right),
                        b'D' => Ok(Key::Left),
                        b'H' => Ok(Key::Home),
                        b'F' => Ok(Key::End),
                        _ => Ok(Key::Esc),
                    }
                }
                b'<' => Ok(Key::Alt('<')),
                b'>' => Ok(Key::Alt('>')),
                c if c.is_ascii() => Ok(Key::Alt(c as char)),
                _ => Ok(Key::Esc),
            }
        }
        1..=26 => match b {
            1 => Ok(Key::Ctrl('a')),
            2 => Ok(Key::Ctrl('b')),
            3 => Ok(Key::Ctrl('c')),
            4 => Ok(Key::Ctrl('d')),
            5 => Ok(Key::Ctrl('e')),
            6 => Ok(Key::Ctrl('f')),
            7 => Ok(Key::Ctrl('g')),
            8 => Ok(Key::Backspace),
            9 => Ok(Key::Tab),
            10 => Ok(Key::Enter),
            11 => Ok(Key::Ctrl('k')),
            12 => Ok(Key::Ctrl('l')),
            13 => Ok(Key::Enter),
            14 => Ok(Key::Ctrl('n')),
            15 => Ok(Key::Ctrl('o')),
            16 => Ok(Key::Ctrl('p')),
            17 => Ok(Key::Ctrl('q')),
            18 => Ok(Key::Ctrl('r')),
            19 => Ok(Key::Ctrl('s')),
            20 => Ok(Key::Ctrl('t')),
            21 => Ok(Key::Ctrl('u')),
            22 => Ok(Key::Ctrl('v')),
            23 => Ok(Key::Ctrl('w')),
            24 => Ok(Key::Ctrl('x')),
            25 => Ok(Key::Ctrl('y')),
            26 => Ok(Key::Ctrl('z')),
            _ => Ok(Key::Ctrl((b + b'a' - 1) as char)),
        },
        29 => Ok(Key::Ctrl(']')),
        31 => Ok(Key::Ctrl('?')),
        127 => Ok(Key::Backspace),
        _ => {
            let mut bytes = vec![b];
            let len = if b & 0b1000_0000 == 0 {
                1
            } else if b & 0b1110_0000 == 0b1100_0000 {
                2
            } else if b & 0b1111_0000 == 0b1110_0000 {
                3
            } else if b & 0b1111_1000 == 0b1111_0000 {
                4
            } else {
                1
            };
            while bytes.len() < len {
                let mut b_extra = [0u8; 1];
                if stdin.read(&mut b_extra)? == 0 {
                    break;
                }
                bytes.push(b_extra[0]);
            }
            if let Ok(s) = std::str::from_utf8(&bytes) {
                if let Some(c) = s.chars().next() {
                    return Ok(Key::Char(c));
                }
            }
            Ok(Key::Char(b as char))
        }
    }
}

fn has_input() -> io::Result<bool> {
    let stdin_fd = io::stdin().as_raw_fd();
    let mut fds = libc_pollfd {
        fd: stdin_fd,
        events: 1,
        revents: 0,
    };
    let ret = poll(&mut fds, 1, 10);
    Ok(ret > 0 && (fds.revents & 1) != 0)
}

